test('current membership source and full historical prior records have exact independent-input bindings',()=>{assert.equal(sha(raw('docs/region-membership-source-20261012.json')),expectedSource);assert.equal(sha(raw('docs/region-membership-history-20261012.json')),expectedHistory);assert.equal(c.membershipSourceSha256,expectedSource);assert.equal(p.membershipSourceSha256,expectedSource);assert.equal(record.priorHistorySha256,expectedHistory);assert.equal(record.baselineSourceRevision,'c1cecbeeb0dd7efb53818742732567e7b07480ab');assert.equal(record.independentImpactReviewSha256,'15a747925ff45021383467ace4f83053011d055c4a61c4a49d694355c3b9db9b');assert.equal(record.effectiveDateKorea,'2026-10-12');assert.equal(record.effectiveDateDistinction.generalOrdinance2655,'2026-08-31');assert.equal(record.countAccounting.customerCopyRevisedArticles,0);assert.equal(c.membershipRevision.customerCopyRevisedArticles,0);assert.equal(record.publicationForThisRevision.visualQa,'DEFERRED_NOT_PASS');for(const k of ['dispatch','publicVerification','searchSubmission'])assert.equal(record.publicationForThisRevision[k],'not_performed');});
