test('only the administrative Godeok alias splits and all37 legal units/representatives remain exact',()=>{assert.equal(c.units.length,37);assert.deepEqual(c.units,history.coverage.units);assert.deepEqual(c.representatives,history.coverage.representatives);assert.deepEqual(c.districts,history.coverage.districts);assert.equal(c.administrativeCrosswalk.length,26);assert(!c.administrativeCrosswalk.some(x=>x.aliasKey==='평택시/행정/고덕동'));assert.deepEqual(c.administrativeCrosswalk.filter(x=>!['고덕1동','고덕2동'].includes(x.name)),history.coverage.administrativeCrosswalk.filter(x=>x.name!=='고덕동'));assert.deepEqual(c.administrativeCrosswalk,record.administrativeCrosswalk);for(const name of ['고덕1동','고덕2동']){const row=c.administrativeCrosswalk.find(x=>x.name===name);assert.equal(row.aliasKey,'평택시/행정/'+name);assert.deepEqual(row.relations,[{unitKey:'평택시/법정동/고덕동',scope:'partial'}]);}for(const name of ['통복동','동삭동'])assert.deepEqual(c.administrativeCrosswalk.find(x=>x.name===name),history.coverage.administrativeCrosswalk.find(x=>x.name===name));});
